<?php
require dirname(__DIR__).'/app/bootstrap.php';Auth::requireAdmin();$adminTitle='Akun Superadmin';if(is_post()){try{verify_csrf();$action=(string)$_POST['action'];if($action==='create'){$name=trim((string)$_POST['name']);$email=filter_var($_POST['email'],FILTER_VALIDATE_EMAIL);$password=(string)$_POST['password'];if(!$email||strlen($password)<10)throw new RuntimeException('Email tidak valid atau password kurang dari 10 karakter.');$stmt=db()->prepare("INSERT INTO users(name,email,password_hash,role,is_active,created_at,updated_at) VALUES(?,?,?,'superadmin',1,NOW(),NOW())");$stmt->execute([$name,$email,password_hash($password,PASSWORD_DEFAULT)]);audit('CREATE_ADMIN','users',(int)db()->lastInsertId());flash('success','Akun Superadmin dibuat.');}elseif($action==='password'){$password=(string)$_POST['password'];if(strlen($password)<10)throw new RuntimeException('Password minimal 10 karakter.');db()->prepare('UPDATE users SET password_hash=?,updated_at=NOW() WHERE id=?')->execute([password_hash($password,PASSWORD_DEFAULT),Auth::id()]);audit('CHANGE_PASSWORD','users',Auth::id());flash('success','Password berhasil diperbarui.');}elseif($action==='toggle'){$id=(int)$_POST['id'];if($id===Auth::id())throw new RuntimeException('Akun yang sedang digunakan tidak dapat dinonaktifkan.');db()->prepare('UPDATE users SET is_active=1-is_active,updated_at=NOW() WHERE id=?')->execute([$id]);audit('TOGGLE_ADMIN','users',$id);flash('success','Status akun diperbarui.');}redirect('admin/users.php');}catch(Throwable $e){flash('danger',$e->getMessage());redirect('admin/users.php');}}
$users=db()->query("SELECT id,name,email,is_active,last_login_at,created_at FROM users WHERE role='superadmin' ORDER BY id")->fetchAll();require __DIR__.'/partials/header.php';
?>
<div class="row g-4"><div class="col-xl-5"><div class="admin-card p-4 mb-4"><h5>Tambah Superadmin</h5><form method="post" class="row g-3 mt-1"><?= csrf_field() ?><input type="hidden" name="action" value="create"><div class="col-12"><label class="form-label">Nama</label><input class="form-control" name="name" required></div><div class="col-12"><label class="form-label">Email</label><input class="form-control" type="email" name="email" required></div><div class="col-12"><label class="form-label">Password</label><input class="form-control" type="password" name="password" minlength="10" required></div><div class="col-12"><button class="btn btn-admin">Tambah Akun</button></div></form></div><div class="admin-card p-4"><h5>Ganti Password Saya</h5><form method="post" class="row g-3 mt-1"><?= csrf_field() ?><input type="hidden" name="action" value="password"><div class="col-12"><label class="form-label">Password Baru</label><input class="form-control" type="password" name="password" minlength="10" required></div><div class="col-12"><button class="btn btn-gold-admin">Perbarui Password</button></div></form></div></div><div class="col-xl-7"><div class="admin-card overflow-hidden"><div class="p-4"><h5 class="mb-0">Daftar Akun</h5></div><div class="table-responsive"><table class="table table-admin"><thead><tr><th>Nama</th><th>Email</th><th>Login Terakhir</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($users as $u):?><tr><td><strong><?= e($u['name']) ?></strong></td><td><?= e($u['email']) ?></td><td><?= indonesia_date($u['last_login_at'],true) ?></td><td><?= $u['is_active']?'<span class="badge text-bg-success">Aktif</span>':'<span class="badge text-bg-secondary">Nonaktif</span>' ?></td><td><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?= (int)$u['id'] ?>"><button class="btn btn-sm btn-outline-secondary" <?= $u['id']===Auth::id()?'disabled':'' ?>>Ubah Status</button></form></td></tr><?php endforeach;?></tbody></table></div></div></div></div>
